    const separate=btn("",()=>{const parts=splitCreativePrompt(getDraft?.(key)||"");if(!parts.direction)return;const next=storage.read();if(!active(key))next.overrides[key]=parts.direction;if(commit(next,c)){setDraft?.(key,parts.scene);previewText();separate.hidden=true;}});separate.dataset.mixAction="separate";
    section.addEventListener("input",()=>{const next=storage.read();next.overrides[key]=section.value;commit(next,c);});
